with candidates (topic, prompt, options, correct_answer, explanation) as (
  values
  -- Introduction and measurement (8)
  ($q$Introduction to Chemistry$q$, $q$A student measures the same sample repeatedly and gets nearly identical values that are all too high. How are the readings best described?$q$, $q${"A":"Precise but inaccurate","B":"Accurate but imprecise","C":"Both exact and unbiased","D":"Random without pattern"}$q$::jsonb, $q$A$q$, $q$Close repeated readings show precision; being systematically high means poor accuracy.$q$),
  ($q$Introduction to Chemistry$q$, $q$Why should a chemist record a measurement with its unit?$q$, $q${"A":"Units change the sample mass","B":"A number alone cannot identify the physical quantity","C":"Units remove every error","D":"Units make experiments unnecessary"}$q$::jsonb, $q$B$q$, $q$The unit specifies the scale and kind of quantity, such as grams or millilitres.$q$),
  ($q$Introduction to Chemistry$q$, $q$A claim predicts that a substance dissolves faster in warm water. What should be done next to test it scientifically?$q$, $q${"A":"Declare it true without evidence","B":"Change several factors at once","C":"Compare controlled dissolving trials at different temperatures","D":"Ignore measurements"}$q$::jsonb, $q$C$q$, $q$A controlled comparison isolates temperature as the changed variable.$q$),
  ($q$Introduction to Chemistry$q$, $q$Why are repeated measurements useful?$q$, $q${"A":"They guarantee the first result is right","B":"They change the chemical formula","C":"They remove all need for controls","D":"They help reveal random variation"}$q$::jsonb, $q$D$q$, $q$Repeats show the spread of results and can improve confidence in an average.$q$),
  ($q$Introduction to Chemistry$q$, $q$A student wants to compare reaction times fairly. Which factor should remain the same besides the one deliberately changed?$q$, $q${"A":"The amounts of reactants","B":"The written conclusion","C":"The student's expectation","D":"The order of the alphabet"}$q$::jsonb, $q$A$q$, $q$Keeping reactant amounts constant prevents a second variable from changing the result.$q$),
  ($q$Introduction to Chemistry$q$, $q$Which observation is evidence of a chemical change rather than merely melting?$q$, $q${"A":"A solid becomes liquid","B":"A new substance with different properties forms","C":"The container is moved","D":"Water is poured into another cup"}$q$::jsonb, $q$B$q$, $q$Chemical change produces substances with new compositions and properties.$q$),
  ($q$Introduction to Chemistry$q$, $q$Why is a mass of 2.0 g more informative than simply writing 2?$q$, $q${"A":"It makes the sample heavier","B":"It is a temperature","C":"It supplies both unit and reported precision","D":"It proves the scale is perfect"}$q$::jsonb, $q$C$q$, $q$The unit says what is measured, and the decimal place indicates measurement resolution.$q$),
  ($q$Introduction to Chemistry$q$, $q$A hypothesis remains useful when which condition is met?$q$, $q${"A":"It cannot be checked","B":"It is based only on authority","C":"It never changes","D":"It makes a testable prediction"}$q$::jsonb, $q$D$q$, $q$A scientific hypothesis must be open to testing against observations.$q$),
  -- Structure of the atom (16)
  ($q$Structure of the Atom$q$, $q$An atom has 11 protons and 12 neutrons. What is its mass number?$q$, $q${"A":"23","B":"11","C":"12","D":"1"}$q$::jsonb, $q$A$q$, $q$Mass number is protons plus neutrons: 11 + 12 = 23.$q$),
  ($q$Structure of the Atom$q$, $q$A neutral atom has 17 protons. How many electrons does it contain?$q$, $q${"A":"34","B":"17","C":"18","D":"0"}$q$::jsonb, $q$B$q$, $q$Neutrality requires equal numbers of positive protons and negative electrons.$q$),
  ($q$Structure of the Atom$q$, $q$Two atoms have the same proton number but different neutron numbers. What are they?$q$, $q${"A":"Different elements","B":"Ions of opposite charge","C":"Isotopes of one element","D":"Molecules"}$q$::jsonb, $q$C$q$, $q$Isotopes share atomic number but differ in neutron count.$q$),
  ($q$Structure of the Atom$q$, $q$A neutral atom loses one electron. What does it become?$q$, $q${"A":"An anion of charge −1","B":"A neutron","C":"A neutral isotope","D":"A cation of charge +1"}$q$::jsonb, $q$D$q$, $q$Losing a negative electron leaves one extra positive charge.$q$),
  ($q$Structure of the Atom$q$, $q$What determines the identity of an element?$q$, $q${"A":"Its number of protons","B":"Its number of neutrons alone","C":"Its physical size","D":"Its phase of matter"}$q$::jsonb, $q$A$q$, $q$Atomic number, the proton count, identifies the element.$q$),
  ($q$Structure of the Atom$q$, $q$An atom has mass number 27 and atomic number 13. How many neutrons does it have?$q$, $q${"A":"40","B":"14","C":"13","D":"27"}$q$::jsonb, $q$B$q$, $q$Neutrons = mass number − proton number = 27 − 13 = 14.$q$),
  ($q$Structure of the Atom$q$, $q$An ion contains 10 electrons and 12 protons. What charge does it carry?$q$, $q${"A":"2−","B":"Neutral","C":"2+","D":"12+"}$q$::jsonb, $q$C$q$, $q$Two more positive protons than electrons give a net charge of 2+.$q$),
  ($q$Structure of the Atom$q$, $q$Where is most of an atom's mass concentrated?$q$, $q${"A":"In its outer electron region","B":"In empty space","C":"Only in the last shell","D":"In its nucleus"}$q$::jsonb, $q$D$q$, $q$Protons and neutrons in the nucleus carry nearly all atomic mass.$q$),
  ($q$Structure of the Atom$q$, $q$Why do isotopes of chlorine react similarly?$q$, $q${"A":"They have the same electron arrangement when neutral","B":"They have identical masses","C":"Their neutron numbers are equal","D":"They contain no nuclei"}$q$::jsonb, $q$A$q$, $q$Chemical reactions depend mainly on electrons, which neutral isotopes share.$q$),
  ($q$Structure of the Atom$q$, $q$An atom's electron arrangement is 2,8,1. How many valence electrons does it have?$q$, $q${"A":"8","B":"1","C":"11","D":"2"}$q$::jsonb, $q$B$q$, $q$The last occupied shell contains one electron.$q$),
  ($q$Structure of the Atom$q$, $q$An atom's electron arrangement is 2,8,7. How many electrons will it most readily gain to fill its outer shell?$q$, $q${"A":"7","B":"2","C":"1","D":"8"}$q$::jsonb, $q$C$q$, $q$The outer shell has seven and needs one more to reach eight.$q$),
  ($q$Structure of the Atom$q$, $q$Which subatomic particle has no electric charge?$q$, $q${"A":"Proton","B":"Electron","C":"Cation","D":"Neutron"}$q$::jsonb, $q$D$q$, $q$Neutrons are electrically neutral particles in the nucleus.$q$),
  ($q$Structure of the Atom$q$, $q$A magnesium atom loses two electrons. Which ion forms?$q$, $q${"A":"Mg²⁺","B":"Mg²⁻","C":"Mg⁺","D":"Mg⁰"}$q$::jsonb, $q$A$q$, $q$Losing two negatively charged electrons leaves magnesium with a 2+ charge.$q$),
  ($q$Structure of the Atom$q$, $q$A chlorine atom gains one electron. Which ion forms?$q$, $q${"A":"Cl⁺","B":"Cl⁻","C":"Cl²⁺","D":"Cl⁰"}$q$::jsonb, $q$B$q$, $q$Gaining an electron gives chlorine a net 1− charge.$q$),
  ($q$Structure of the Atom$q$, $q$Why is the mass number normally a whole number?$q$, $q${"A":"It measures the atom's temperature","B":"It measures grams exactly","C":"It counts nucleons","D":"It is the number of shells"}$q$::jsonb, $q$C$q$, $q$Mass number counts the integer total of protons and neutrons.$q$),
  ($q$Structure of the Atom$q$, $q$An atom has 6 protons and 6 neutrons. Which pair is correct?$q$, $q${"A":"Atomic number 12, mass number 6","B":"Atomic number 6, mass number 6","C":"Atomic number 12, mass number 12","D":"Atomic number 6, mass number 12"}$q$::jsonb, $q$D$q$, $q$Atomic number = 6 protons; mass number = 6 + 6 = 12.$q$),
  -- Mixtures and purity (8)
  ($q$Separation of Mixtures$q$, $q$Sand is mixed with salt. What first step can separate the insoluble sand from dissolved salt?$q$, $q${"A":"Dissolve salt in water, then filter","B":"Use a magnet for salt","C":"Freeze the dry mixture","D":"Add more sand"}$q$::jsonb, $q$A$q$, $q$Salt dissolves but sand does not; filtration then retains sand.$q$),
  ($q$Separation of Mixtures$q$, $q$How can pure water be collected from salty water?$q$, $q${"A":"Simple filtration","B":"Distillation","C":"Use of a magnet","D":"Sieving"}$q$::jsonb, $q$B$q$, $q$Water vaporizes and condenses, leaving nonvolatile dissolved salt behind.$q$),
  ($q$Separation of Mixtures$q$, $q$Why is fractional distillation useful for two miscible liquids with different boiling points?$q$, $q${"A":"It changes their chemical formulae","B":"It makes both solid","C":"It separates by volatility","D":"It uses magnetism"}$q$::jsonb, $q$C$q$, $q$The more volatile component vaporizes and condenses preferentially.$q$),
  ($q$Separation of Mixtures$q$, $q$A liquid boils over a broad temperature range rather than a sharp point. What is a likely explanation?$q$, $q${"A":"It has no particles","B":"It is certainly an element","C":"It cannot evaporate","D":"It contains impurities or mixed components"}$q$::jsonb, $q$D$q$, $q$A pure substance at fixed pressure has a characteristic sharp boiling point; mixtures may span a range.$q$),
  ($q$Separation of Mixtures$q$, $q$Which method is suited to separating coloured dyes based on differing movement through a medium?$q$, $q${"A":"Chromatography","B":"Decantation only","C":"Sieving","D":"Magnetization"}$q$::jsonb, $q$A$q$, $q$Chromatography separates components by differing affinities for mobile and stationary phases.$q$),
  ($q$Separation of Mixtures$q$, $q$A mixture of iron filings and sulfur powder is present before reaction. Which property can separate them?$q$, $q${"A":"Identical melting points","B":"Magnetism of iron","C":"The smell of sulfur","D":"Equal solubility"}$q$::jsonb, $q$B$q$, $q$A magnet attracts iron filings but not sulfur powder.$q$),
  ($q$Separation of Mixtures$q$, $q$Why can a dissolved sugar solution not be separated by ordinary filtration?$q$, $q${"A":"Sugar has no mass","B":"Water becomes a solid","C":"Dissolved particles pass through the filter","D":"Filter paper is magnetic"}$q$::jsonb, $q$C$q$, $q$Dissolved molecules are much smaller than filter pores.$q$),
  ($q$Separation of Mixtures$q$, $q$How could crystals of a dissolved salt be obtained from its aqueous solution?$q$, $q${"A":"Add another insoluble solid","B":"Use a magnet","C":"Filter the clear solution only","D":"Concentrate it and allow it to cool"}$q$::jsonb, $q$D$q$, $q$Evaporating some solvent then cooling can make the solution supersaturated and form crystals.$q$),
  -- Periodic chemistry, first 8 of 16
  ($q$Periodic Chemistry$q$, $q$Elements in one group usually react similarly because they have the same what?$q$, $q${"A":"Number of outer-shell electrons","B":"Mass number","C":"Number of neutrons","D":"Atomic radius"}$q$::jsonb, $q$A$q$, $q$Shared valence electron counts give similar chemical behaviour.$q$),
  ($q$Periodic Chemistry$q$, $q$Across a period from left to right, what generally happens to atomic number?$q$, $q${"A":"It decreases","B":"It increases one step at a time","C":"It stays fixed","D":"It becomes zero"}$q$::jsonb, $q$B$q$, $q$Each successive element has one more proton.$q$),
  ($q$Periodic Chemistry$q$, $q$Why is sodium placed in Group 1?$q$, $q${"A":"It has one neutron","B":"It is a noble gas","C":"It has one valence electron","D":"It has one shell"}$q$::jsonb, $q$C$q$, $q$Its electron arrangement is 2,8,1, leaving one outer electron.$q$),
  ($q$Periodic Chemistry$q$, $q$Across Period 3 from sodium toward chlorine, how does metallic character generally change?$q$, $q${"A":"It increases","B":"It stays constant","C":"It becomes undefined","D":"It decreases"}$q$::jsonb, $q$D$q$, $q$Elements change from reactive metals through metalloids toward nonmetals.$q$),
  ($q$Periodic Chemistry$q$, $q$Why are noble gases generally unreactive?$q$, $q${"A":"Their outer electron shells are filled","B":"They have no protons","C":"They exist only as solids","D":"Their atomic numbers are zero"}$q$::jsonb, $q$A$q$, $q$A complete valence shell gives little tendency to gain or lose electrons.$q$),
  ($q$Periodic Chemistry$q$, $q$Which property generally increases down Group 1?$q$, $q${"A":"Ionization energy","B":"Atomic radius","C":"Attraction of outer electron to nucleus","D":"Electronegativity"}$q$::jsonb, $q$B$q$, $q$Each step down adds an electron shell, increasing atomic radius.$q$),
  ($q$Periodic Chemistry$q$, $q$Which Period 3 element forms an acidic oxide SO₂?$q$, $q${"A":"Magnesium","B":"Sodium","C":"Sulfur","D":"Aluminium"}$q$::jsonb, $q$C$q$, $q$SO₂ is sulfur dioxide; sulfur is a Period 3 nonmetal.$q$),
  ($q$Periodic Chemistry$q$, $q$Why do Group 17 elements tend to form 1− ions?$q$, $q${"A":"They lose seven neutrons","B":"They lose one proton","C":"They gain seven electrons","D":"They gain one electron to fill the valence shell"}$q$::jsonb, $q$D$q$, $q$Halogens have seven outer electrons and gain one to complete an octet.$q$),
  ($q$Periodic Chemistry$q$, $q$Which Period 3 oxide is strongly basic when dissolved in water?$q$, $q${"A":"Na₂O","B":"SO₃","C":"P₄O₁₀","D":"SiO₂"}$q$::jsonb, $q$A$q$, $q$Sodium oxide forms sodium hydroxide with water, giving an alkaline solution.$q$),
  ($q$Periodic Chemistry$q$, $q$What happens to the number of occupied electron shells down a group?$q$, $q${"A":"It falls","B":"It increases","C":"It stays one","D":"It becomes zero"}$q$::jsonb, $q$B$q$, $q$Each next period adds a principal electron shell.$q$),
  ($q$Periodic Chemistry$q$, $q$A Period 3 atom has electron arrangement 2,8,2. Which element is it?$q$, $q${"A":"Sodium","B":"Aluminium","C":"Magnesium","D":"Sulfur"}$q$::jsonb, $q$C$q$, $q$The arrangement totals 12 electrons and two valence electrons, identifying magnesium.$q$),
  ($q$Periodic Chemistry$q$, $q$Across Period 3, why does atomic radius generally decrease?$q$, $q${"A":"A shell is removed at every step","B":"Atoms lose all electrons","C":"Neutrons disappear","D":"Increasing nuclear charge pulls electrons in the same shell closer"}$q$::jsonb, $q$D$q$, $q$More protons attract outer electrons in the same principal shell more strongly.$q$),
  ($q$Periodic Chemistry$q$, $q$Which element is most likely to form a 3+ ion among these Period 3 elements?$q$, $q${"A":"Aluminium","B":"Chlorine","C":"Argon","D":"Sulfur"}$q$::jsonb, $q$A$q$, $q$Aluminium has three outer electrons and commonly loses them to form Al³⁺.$q$),
  ($q$Periodic Chemistry$q$, $q$Which feature is common among many transition metals?$q$, $q${"A":"They never form ions","B":"They can show variable oxidation states","C":"They are all gases","D":"They lack d electrons entirely"}$q$::jsonb, $q$B$q$, $q$Several transition metals form compounds in more than one oxidation state.$q$),
  ($q$Periodic Chemistry$q$, $q$Why can iron help catalyse the industrial synthesis of ammonia?$q$, $q${"A":"It is consumed as the sole reactant","B":"It changes ammonia into oxygen","C":"It offers a lower-energy reaction pathway","D":"It makes equilibrium impossible"}$q$::jsonb, $q$C$q$, $q$A catalyst speeds the approach to equilibrium by lowering activation energy.$q$),
  ($q$Periodic Chemistry$q$, $q$Which Period 3 element normally exists as a monatomic, unreactive gas?$q$, $q${"A":"Sodium","B":"Chlorine","C":"Phosphorus","D":"Argon"}$q$::jsonb, $q$D$q$, $q$Argon has a filled outer shell and normally exists as separate atoms.$q$),
  -- Chemical bonding (16)
  ($q$Chemical Bonding$q$, $q$When sodium reacts with chlorine, what chiefly holds the resulting ions together?$q$, $q${"A":"Electrostatic attraction between opposite charges","B":"Shared neutrons","C":"Magnetism between nuclei","D":"Hydrogen bonding only"}$q$::jsonb, $q$A$q$, $q$Na⁺ and Cl⁻ attract each other to form an ionic lattice.$q$),
  ($q$Chemical Bonding$q$, $q$Why does solid sodium chloride not conduct electricity well?$q$, $q${"A":"It contains no ions","B":"Its ions are fixed in a lattice","C":"Its electrons vanish","D":"It has no charge anywhere"}$q$::jsonb, $q$B$q$, $q$The ions carry charge but cannot move freely in the solid lattice.$q$),
  ($q$Chemical Bonding$q$, $q$What changes when molten sodium chloride conducts electricity?$q$, $q${"A":"Electrons become protons","B":"Its ions disappear","C":"The ions can move","D":"It becomes a covalent molecule"}$q$::jsonb, $q$C$q$, $q$Melting frees ions to migrate and carry charge.$q$),
  ($q$Chemical Bonding$q$, $q$In a covalent bond between two hydrogen atoms, what is shared?$q$, $q${"A":"One proton","B":"A neutron pair","C":"Whole nuclei","D":"A pair of electrons"}$q$::jsonb, $q$D$q$, $q$Each hydrogen contributes an electron to a shared pair.$q$),
  ($q$Chemical Bonding$q$, $q$Why does methane have the formula CH₄?$q$, $q${"A":"Carbon forms four bonds with four hydrogen atoms","B":"Hydrogen has four valence electrons","C":"Carbon loses four protons","D":"Methane is ionic"}$q$::jsonb, $q$A$q$, $q$Carbon shares one pair with each of four hydrogen atoms.$q$),
  ($q$Chemical Bonding$q$, $q$What distinguishes a coordinate covalent bond in its formation?$q$, $q${"A":"It involves no electrons","B":"Both shared electrons initially come from one atom","C":"It occurs only between metals","D":"It is always weaker than every other bond"}$q$::jsonb, $q$B$q$, $q$One donor atom supplies the electron pair shared with an acceptor.$q$),
  ($q$Chemical Bonding$q$, $q$Which formula is correct for the compound from Mg²⁺ and Cl⁻?$q$, $q${"A":"MgCl","B":"Mg₂Cl","C":"MgCl₂","D":"Mg₂Cl₃"}$q$::jsonb, $q$C$q$, $q$Two chloride ions, each 1−, balance one magnesium ion, 2+.$q$),
  ($q$Chemical Bonding$q$, $q$Why does diamond have a very high melting point?$q$, $q${"A":"Its molecules are tiny","B":"Its electrons cannot move","C":"It contains free ions","D":"Many strong covalent bonds form a giant network"}$q$::jsonb, $q$D$q$, $q$Melting diamond requires breaking extensive covalent bonds throughout a network.$q$),
  ($q$Chemical Bonding$q$, $q$Why can graphite conduct electricity although diamond cannot?$q$, $q${"A":"Graphite has delocalized electrons that move within its layers","B":"Graphite is an ionic salt","C":"Diamond has no carbon","D":"Graphite contains only protons"}$q$::jsonb, $q$A$q$, $q$Each graphite carbon contributes an electron to a delocalized system within its layers that carries charge.$q$),
  ($q$Chemical Bonding$q$, $q$What chiefly holds a metal crystal together?$q$, $q${"A":"Bonds between neutral molecules only","B":"Attraction between positive metal ions and delocalized electrons","C":"Attraction between two negative ions","D":"Shared neutrons"}$q$::jsonb, $q$B$q$, $q$Metallic bonding is electrostatic attraction within a lattice of ions and mobile electrons.$q$),
  ($q$Chemical Bonding$q$, $q$Why is water polar?$q$, $q${"A":"Oxygen and hydrogen attract electrons equally","B":"Its molecule is linear","C":"Unequal sharing and bent shape produce a net dipole","D":"It contains sodium ions"}$q$::jsonb, $q$C$q$, $q$Oxygen pulls bonding electrons more strongly, and the bent geometry prevents dipoles cancelling.$q$),
  ($q$Chemical Bonding$q$, $q$Why do many simple covalent substances have low boiling points?$q$, $q${"A":"They have no intramolecular bonds","B":"They contain no particles","C":"They are all gases at every temperature","D":"Intermolecular attractions are relatively weak"}$q$::jsonb, $q$D$q$, $q$Boiling separates molecules rather than breaking their strong internal covalent bonds.$q$),
  ($q$Chemical Bonding$q$, $q$Which bonding is present in a molecule of oxygen gas, O₂?$q$, $q${"A":"A double covalent bond","B":"An ionic bond between O⁺ and O⁻","C":"A metallic bond","D":"No bond"}$q$::jsonb, $q$A$q$, $q$The two oxygen atoms share two electron pairs.$q$),
  ($q$Chemical Bonding$q$, $q$Why does a salt dissolve in water more readily when hydration compensates for lattice attraction?$q$, $q${"A":"Water has no polarity","B":"Water's polar molecules stabilize separated ions","C":"All lattice energy becomes zero","D":"Salt turns into an element"}$q$::jsonb, $q$B$q$, $q$Ion-dipole attractions between water and ions help overcome the lattice.$q$),
  ($q$Chemical Bonding$q$, $q$Which pair is most likely to form an ionic compound?$q$, $q${"A":"Carbon and hydrogen","B":"Oxygen and nitrogen","C":"Potassium and bromine","D":"Chlorine and chlorine"}$q$::jsonb, $q$C$q$, $q$A reactive metal can transfer an electron to a halogen, yielding K⁺ and Br⁻.$q$),
  ($q$Chemical Bonding$q$, $q$Why can a metal be shaped without shattering its bonding network?$q$, $q${"A":"The metal has no bonds","B":"Its atoms become gases","C":"All its electrons are fixed in pairs","D":"Metal-ion layers can slide while delocalized electrons maintain attraction"}$q$::jsonb, $q$D$q$, $q$Non-directional metallic bonding persists as layers of ions move.$q$),
  -- Stoichiometry, first 16 of 24
  ($q$Stoichiometry and Chemical Reactions$q$, $q$How many moles are in 18 g of water? Use H₂O = 18 g/mol.$q$, $q${"A":"1 mol","B":"18 mol","C":"0.5 mol","D":"36 mol"}$q$::jsonb, $q$A$q$, $q$n = m/M = 18/18 = 1 mol.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$What mass is 2 mol of CO₂ if its molar mass is 44 g/mol?$q$, $q${"A":"22 g","B":"88 g","C":"46 g","D":"176 g"}$q$::jsonb, $q$B$q$, $q$m = nM = 2 × 44 = 88 g.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$Balance H₂ + O₂ → H₂O. What is the coefficient of H₂O when smallest whole numbers are used?$q$, $q${"A":"1","B":"3","C":"2","D":"4"}$q$::jsonb, $q$C$q$, $q$The balanced equation is 2H₂ + O₂ → 2H₂O.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$In 2H₂ + O₂ → 2H₂O, what mole ratio of hydrogen to oxygen is required?$q$, $q${"A":"1:2","B":"1:1","C":"2:2","D":"2:1"}$q$::jsonb, $q$D$q$, $q$Equation coefficients give 2 mol H₂ for each 1 mol O₂.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$How many molecules are in 2 mol of a substance? Use Avogadro constant 6.02 × 10²³ mol⁻¹.$q$, $q${"A":"1.204 × 10²⁴","B":"3.01 × 10²³","C":"6.02 × 10²³","D":"12.04 × 10²³ mol"}$q$::jsonb, $q$A$q$, $q$Number = 2 × 6.02 × 10²³ = 1.204 × 10²⁴ molecules.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$A compound contains 24 g carbon and 4 g hydrogen. Using C = 12, H = 1, what is its empirical formula?$q$, $q${"A":"CH","B":"CH₂","C":"C₂H","D":"C₂H₄"}$q$::jsonb, $q$B$q$, $q$Moles: C = 24/12 = 2, H = 4/1 = 4. Divide by 2 to get C:H = 1:2, so CH₂.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$A substance has empirical formula CH₂ and molar mass 42 g/mol. What is its molecular formula? Use C = 12, H = 1.$q$, $q${"A":"CH₂","B":"C₂H₄","C":"C₃H₆","D":"C₄H₈"}$q$::jsonb, $q$C$q$, $q$Empirical mass = 14; 42/14 = 3, so multiply CH₂ by 3 to obtain C₃H₆.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$What does a balanced chemical equation conserve?$q$, $q${"A":"Only colour","B":"Only volume","C":"Only temperature","D":"Atoms of each element"}$q$::jsonb, $q$D$q$, $q$Coefficients ensure the number of each kind of atom is equal on both sides.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$CaCO₃ → CaO + CO₂. If 1 mol CaCO₃ decomposes fully, how many moles of CO₂ form?$q$, $q${"A":"1 mol","B":"2 mol","C":"0.5 mol","D":"3 mol"}$q$::jsonb, $q$A$q$, $q$The balanced equation has a 1:1 mol ratio between CaCO₃ and CO₂.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$What mass of oxygen is needed to react with 4 g hydrogen in 2H₂ + O₂ → 2H₂O? Use H₂ = 2, O₂ = 32 g/mol.$q$, $q${"A":"16 g","B":"32 g","C":"64 g","D":"8 g"}$q$::jsonb, $q$B$q$, $q$4 g H₂ = 2 mol. The 2:1 ratio needs 1 mol O₂, which has mass 32 g.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$How many moles are in 5.6 L of a gas at STP if molar volume is 22.4 L/mol?$q$, $q${"A":"4 mol","B":"0.5 mol","C":"0.25 mol","D":"2 mol"}$q$::jsonb, $q$C$q$, $q$n = V/Vₘ = 5.6/22.4 = 0.25 mol.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$A solution contains 0.5 mol solute in 1 L. What is its concentration?$q$, $q${"A":"2 mol/L","B":"1.5 mol/L","C":"0.05 mol/L","D":"0.5 mol/L"}$q$::jsonb, $q$D$q$, $q$c = n/V = 0.5/1 = 0.5 mol/L.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$What mass of NaCl is present in 0.5 mol if M(NaCl) = 58.5 g/mol?$q$, $q${"A":"29.25 g","B":"117 g","C":"58.5 g","D":"0.00855 g"}$q$::jsonb, $q$A$q$, $q$m = nM = 0.5 × 58.5 = 29.25 g.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$A reaction makes 8 g product when 10 g is theoretically possible. What is the percentage yield?$q$, $q${"A":"125%","B":"80%","C":"20%","D":"8%"}$q$::jsonb, $q$B$q$, $q$Percentage yield = actual/theoretical × 100 = 8/10 × 100 = 80%.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$In N₂ + 3H₂ → 2NH₃, how many moles NH₃ can 1 mol N₂ make with excess H₂?$q$, $q${"A":"1 mol","B":"3 mol","C":"2 mol","D":"6 mol"}$q$::jsonb, $q$C$q$, $q$The coefficients give 1 mol N₂ → 2 mol NH₃.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$In 2Na + Cl₂ → 2NaCl, which reactant limits production if 2 mol Na reacts with 2 mol Cl₂?$q$, $q${"A":"Cl₂","B":"Both are exactly used","C":"Neither because the reaction is impossible","D":"Na"}$q$::jsonb, $q$D$q$, $q$2 mol Na needs only 1 mol Cl₂; sodium runs out while chlorine remains.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$What is the molar mass of H₂SO₄? Use H = 1, S = 32, O = 16.$q$, $q${"A":"98 g/mol","B":"49 g/mol","C":"64 g/mol","D":"100 g/mol"}$q$::jsonb, $q$A$q$, $q$M = 2(1) + 32 + 4(16) = 2 + 32 + 64 = 98 g/mol.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$How many oxygen atoms occur in 3 formula units of Ca(NO₃)₂?$q$, $q${"A":"6","B":"18","C":"9","D":"12"}$q$::jsonb, $q$B$q$, $q$Each formula unit has two nitrate groups with three oxygen atoms each: 2 × 3 = 6; three units have 18.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$A hydrocarbon contains 12 g carbon and 3 g hydrogen. What is the simplest C:H mole ratio? Use C = 12, H = 1.$q$, $q${"A":"3:1","B":"12:3","C":"1:3","D":"1:4"}$q$::jsonb, $q$C$q$, $q$C moles = 12/12 = 1; H moles = 3/1 = 3, so C:H = 1:3.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$What volume does 0.5 mol ideal gas occupy at STP if molar volume is 22.4 L/mol?$q$, $q${"A":"44.8 L","B":"22.4 L","C":"5.6 L","D":"11.2 L"}$q$::jsonb, $q$D$q$, $q$V = nVₘ = 0.5 × 22.4 = 11.2 L.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$In CaCO₃ → CaO + CO₂, what mass of CO₂ comes from 100 g CaCO₃? Use molar masses 100 and 44 g/mol.$q$, $q${"A":"44 g","B":"100 g","C":"22 g","D":"144 g"}$q$::jsonb, $q$A$q$, $q$100 g CaCO₃ = 1 mol; the 1:1 ratio produces 1 mol CO₂ = 44 g.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$A 250 mL solution contains 0.05 mol solute. What is its molarity?$q$, $q${"A":"0.0125 mol/L","B":"0.20 mol/L","C":"5 mol/L","D":"1.25 mol/L"}$q$::jsonb, $q$B$q$, $q$250 mL = 0.250 L; c = n/V = 0.05/0.250 = 0.20 mol/L.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$In 2Mg + O₂ → 2MgO, what mass of MgO forms from 48 g Mg if oxygen is excess? Use Mg = 24, O = 16.$q$, $q${"A":"40 g","B":"48 g","C":"80 g","D":"96 g"}$q$::jsonb, $q$C$q$, $q$48 g Mg = 2 mol. The ratio to MgO is 1:1, so 2 mol MgO × 40 g/mol = 80 g.$q$),
  ($q$Stoichiometry and Chemical Reactions$q$, $q$A compound contains 12 g carbon and 16 g oxygen. What is its simplest formula? Use C = 12, O = 16.$q$, $q${"A":"CO₂","B":"C₂O","C":"C₂O₃","D":"CO"}$q$::jsonb, $q$D$q$, $q$Carbon moles = 12/12 = 1; oxygen moles = 16/16 = 1. The 1:1 ratio gives CO.$q$),
  -- States of matter (8)
  ($q$States of Matter$q$, $q$Why can a gas fill the entire available container?$q$, $q${"A":"Its particles move freely with large spaces between them","B":"Its particles are fixed in a lattice","C":"It has no particles","D":"Its mass is always zero"}$q$::jsonb, $q$A$q$, $q$Gas particles move randomly and spread through available space.$q$),
  ($q$States of Matter$q$, $q$A drop of dye spreads through still water. What causes the spreading?$q$, $q${"A":"Only gravity","B":"Random particle motion and diffusion","C":"Nuclear decay","D":"Solidification"}$q$::jsonb, $q$B$q$, $q$Molecules move randomly, causing net transfer from higher to lower concentration.$q$),
  ($q$States of Matter$q$, $q$Why is a liquid harder to compress than a gas?$q$, $q${"A":"Liquid molecules have no motion","B":"Gas molecules are all larger","C":"Liquid particles have much less empty space between them","D":"Liquids contain no pressure"}$q$::jsonb, $q$C$q$, $q$Closer particle packing leaves little space to reduce.$q$),
  ($q$States of Matter$q$, $q$A solid melts at a fixed pressure. What chiefly changes during melting?$q$, $q${"A":"Its element identity","B":"Its atomic number","C":"Its total number of particles","D":"Particle arrangement and freedom of movement"}$q$::jsonb, $q$D$q$, $q$Energy weakens the ordered structure so particles can move past one another.$q$),
  ($q$States of Matter$q$, $q$Why does perfume spread more quickly in warm air?$q$, $q${"A":"Particles have greater average kinetic energy","B":"Warm air has no particles","C":"Perfume becomes a metal","D":"Gravity reverses"}$q$::jsonb, $q$A$q$, $q$Faster random motion at higher temperature speeds diffusion.$q$),
  ($q$States of Matter$q$, $q$Which change is sublimation?$q$, $q${"A":"Liquid to gas","B":"Solid directly to gas","C":"Gas to liquid","D":"Liquid to solid"}$q$::jsonb, $q$B$q$, $q$Sublimation bypasses the liquid phase.$q$),
  ($q$States of Matter$q$, $q$Water vapour forms droplets on a cold window. What change is this?$q$, $q${"A":"Melting","B":"Sublimation","C":"Condensation","D":"Freezing"}$q$::jsonb, $q$C$q$, $q$Gas loses energy and changes to liquid on the cooler surface.$q$),
  ($q$States of Matter$q$, $q$Which statement fits particles in a crystalline solid?$q$, $q${"A":"They move freely throughout the container","B":"They never vibrate","C":"They are absent","D":"They vibrate around fixed positions"}$q$::jsonb, $q$D$q$, $q$Particles remain in an ordered structure but continue to vibrate.$q$),
  -- Energy changes (8)
  ($q$Energy and Energy Changes$q$, $q$A reaction warms its surroundings. What is its energy classification?$q$, $q${"A":"Exothermic","B":"Endothermic","C":"Isothermal only","D":"No reaction"}$q$::jsonb, $q$A$q$, $q$An exothermic process releases heat to its surroundings.$q$),
  ($q$Energy and Energy Changes$q$, $q$Why does an endothermic process cool its surroundings if no other heat enters?$q$, $q${"A":"It creates cold particles","B":"It absorbs heat from the surroundings","C":"It destroys energy","D":"It emits only light"}$q$::jsonb, $q$B$q$, $q$The process needs energy and draws heat from nearby material.$q$),
  ($q$Energy and Energy Changes$q$, $q$For an exothermic reaction, how does product enthalpy compare with reactant enthalpy?$q$, $q${"A":"It is always equal","B":"It is higher","C":"It is lower","D":"It is undefined"}$q$::jsonb, $q$C$q$, $q$Energy released means products lie at lower enthalpy; ΔH is negative.$q$),
  ($q$Energy and Energy Changes$q$, $q$Why does a reaction with negative ΔH release heat?$q$, $q${"A":"It has no activation energy","B":"Atoms disappear","C":"It must be reversible","D":"The products have less enthalpy than reactants"}$q$::jsonb, $q$D$q$, $q$The enthalpy difference transfers to the surroundings.$q$),
  ($q$Energy and Energy Changes$q$, $q$What is activation energy?$q$, $q${"A":"Minimum energy needed for reacting particles to form products","B":"Energy stored in every neutron","C":"Total heat released by every reaction","D":"Temperature expressed in joules"}$q$::jsonb, $q$A$q$, $q$Particles need enough energy to reach the transition state.$q$),
  ($q$Energy and Energy Changes$q$, $q$How does a catalyst change the energy pathway of a reaction?$q$, $q${"A":"It raises ΔH","B":"It lowers activation energy without changing ΔH","C":"It makes products identical to reactants","D":"It removes reactants"}$q$::jsonb, $q$B$q$, $q$A catalyst offers a lower-energy route while overall reactant-product enthalpy difference stays the same.$q$),
  ($q$Energy and Energy Changes$q$, $q$Breaking bonds requires energy; forming bonds releases it. When is a reaction exothermic?$q$, $q${"A":"When breaking absorbs more than forming releases","B":"Whenever there is a solid","C":"When bond formation releases more than breaking absorbs","D":"Only in sunlight"}$q$::jsonb, $q$C$q$, $q$The excess energy released by new bonds leaves as heat.$q$),
  ($q$Energy and Energy Changes$q$, $q$A reaction absorbs 25 kJ from its surroundings. What sign should its ΔH have?$q$, $q${"A":"Negative","B":"Zero","C":"Either sign","D":"Positive"}$q$::jsonb, $q$D$q$, $q$Heat absorbed by the reacting system gives positive enthalpy change.$q$),
  -- Acids, bases and salts (16)
  ($q$Acids, Bases and Salts$q$, $q$What ion does an acid increase in aqueous solution?$q$, $q${"A":"H₃O⁺","B":"OH⁻","C":"Cl⁻ always","D":"Na⁺ always"}$q$::jsonb, $q$A$q$, $q$An acid donates protons to water, increasing hydronium concentration.$q$),
  ($q$Acids, Bases and Salts$q$, $q$Why is ammonia a base when dissolved in water?$q$, $q${"A":"It donates protons to water","B":"It accepts a proton from water, producing OH⁻","C":"It has no nitrogen","D":"It is a strong acid"}$q$::jsonb, $q$B$q$, $q$NH₃ accepts H⁺ from H₂O, forming NH₄⁺ and OH⁻.$q$),
  ($q$Acids, Bases and Salts$q$, $q$Which pair forms a salt and water in a neutralization reaction?$q$, $q${"A":"Two acids","B":"Two nonmetals","C":"An acid and a base","D":"Two noble gases"}$q$::jsonb, $q$C$q$, $q$Acid-base neutralization commonly yields a salt and water.$q$),
  ($q$Acids, Bases and Salts$q$, $q$What salt forms from HCl and NaOH?$q$, $q${"A":"Na₂SO₄","B":"KCl","C":"CaCO₃","D":"NaCl"}$q$::jsonb, $q$D$q$, $q$HCl + NaOH → NaCl + H₂O.$q$),
  ($q$Acids, Bases and Salts$q$, $q$How does pH change when a strongly acidic solution is diluted with water, without crossing neutrality?$q$, $q${"A":"It rises toward 7","B":"It falls toward 0","C":"It stays exactly fixed","D":"It becomes negative infinity"}$q$::jsonb, $q$A$q$, $q$Dilution reduces hydronium concentration, so pH increases toward neutral.$q$),
  ($q$Acids, Bases and Salts$q$, $q$Which aqueous solution has the highest H₃O⁺ concentration?$q$, $q${"A":"pH 7","B":"pH 2","C":"pH 10","D":"pH 12"}$q$::jsonb, $q$B$q$, $q$Lower pH means higher hydronium concentration; pH 2 is lowest listed.$q$),
  ($q$Acids, Bases and Salts$q$, $q$A pH change from 4 to 3 means hydronium concentration changes by what factor?$q$, $q${"A":"It halves","B":"It doubles","C":"It increases tenfold","D":"It decreases tenfold"}$q$::jsonb, $q$C$q$, $q$pH = −log₁₀[H₃O⁺]; a one-unit decrease means ten times more H₃O⁺.$q$),
  ($q$Acids, Bases and Salts$q$, $q$Why does an aqueous acid conduct electricity?$q$, $q${"A":"Its water turns into metal","B":"It has no charge carriers","C":"It only produces light","D":"Dissolved ions carry charge"}$q$::jsonb, $q$D$q$, $q$Mobile ions allow current to pass through an acidic solution.$q$),
  ($q$Acids, Bases and Salts$q$, $q$Which oxide can act as both an acid and a base in different reactions?$q$, $q${"A":"Al₂O₃","B":"Na₂O","C":"SO₃","D":"CO₂"}$q$::jsonb, $q$A$q$, $q$Aluminium oxide is amphoteric and reacts with both acids and strong bases.$q$),
  ($q$Acids, Bases and Salts$q$, $q$What gas is produced when an acid reacts with a carbonate?$q$, $q${"A":"Oxygen","B":"Carbon dioxide","C":"Hydrogen only","D":"Nitrogen"}$q$::jsonb, $q$B$q$, $q$Acid + carbonate yields salt, water and CO₂.$q$),
  ($q$Acids, Bases and Salts$q$, $q$What is the salt from sulfuric acid and potassium hydroxide when fully neutralized?$q$, $q${"A":"K₂CO₃","B":"KCl","C":"K₂SO₄","D":"KHSO₄ only"}$q$::jsonb, $q$C$q$, $q$H₂SO₄ + 2KOH → K₂SO₄ + 2H₂O.$q$),
  ($q$Acids, Bases and Salts$q$, $q$Why is a strong acid different from a concentrated acid?$q$, $q${"A":"They always mean the same thing","B":"Strength means amount per litre only","C":"Concentration means degree of ionization only","D":"Strength concerns ionization; concentration concerns amount per volume"}$q$::jsonb, $q$D$q$, $q$A dilute acid may be strong if its dissolved molecules ionize almost completely.$q$),
  ($q$Acids, Bases and Salts$q$, $q$A base accepts H⁺ from an acid. Which acid-base theory describes this directly?$q$, $q${"A":"Brønsted-Lowry","B":"Kinetic gas theory","C":"Periodic law","D":"Conservation of mass only"}$q$::jsonb, $q$A$q$, $q$Brønsted-Lowry defines acids as proton donors and bases as proton acceptors.$q$),
  ($q$Acids, Bases and Salts$q$, $q$Which solution is alkaline?$q$, $q${"A":"pH 3","B":"pH 9","C":"pH 7","D":"pH 1"}$q$::jsonb, $q$B$q$, $q$At ordinary conditions, pH above 7 indicates an alkaline solution.$q$),
  ($q$Acids, Bases and Salts$q$, $q$Why does Mg react with dilute HCl to release hydrogen?$q$, $q${"A":"HCl contains oxygen gas","B":"Mg is a nonmetal","C":"Mg displaces hydrogen ions, forming Mg²⁺ and H₂","D":"Chloride becomes nitrogen"}$q$::jsonb, $q$C$q$, $q$Mg + 2HCl → MgCl₂ + H₂; magnesium reduces H⁺ to hydrogen gas.$q$),
  ($q$Acids, Bases and Salts$q$, $q$Which formula represents calcium nitrate?$q$, $q${"A":"CaNO₃","B":"Ca₂NO₃","C":"Ca(NO₃)₃","D":"Ca(NO₃)₂"}$q$::jsonb, $q$D$q$, $q$Ca²⁺ requires two nitrate ions, each NO₃⁻, for a neutral salt.$q$),
  -- Solubility (8)
  ($q$Solubility of Substances$q$, $q$A solution can dissolve no more solute at its present temperature. What is it called?$q$, $q${"A":"Saturated","B":"Unsaturated","C":"Pure solvent","D":"Suspension"}$q$::jsonb, $q$A$q$, $q$A saturated solution holds the maximum dissolved solute at those conditions.$q$),
  ($q$Solubility of Substances$q$, $q$For many solids dissolved in water, what usually happens to solubility as temperature rises?$q$, $q${"A":"It always falls to zero","B":"It often increases","C":"It becomes independent of solute","D":"The solid changes into an element"}$q$::jsonb, $q$B$q$, $q$Dissolution of many solids is favoured by heating, although exceptions exist.$q$),
  ($q$Solubility of Substances$q$, $q$Why does a sealed fizzy drink lose gas when opened?$q$, $q${"A":"Carbon dioxide becomes heavier","B":"Water becomes solid","C":"Lower pressure reduces CO₂ solubility","D":"The bottle makes new oxygen"}$q$::jsonb, $q$C$q$, $q$The pressure above the liquid drops, so dissolved CO₂ escapes.$q$),
  ($q$Solubility of Substances$q$, $q$A substance has solubility 20 g per 100 g water. How much can dissolve in 200 g water at the same temperature?$q$, $q${"A":"10 g","B":"20 g","C":"200 g","D":"40 g"}$q$::jsonb, $q$D$q$, $q$Doubling water mass doubles the maximum solute: 20 × 2 = 40 g.$q$),
  ($q$Solubility of Substances$q$, $q$Why may crystals appear when a hot saturated solution cools?$q$, $q${"A":"Less solute remains soluble at the lower temperature","B":"The solvent gains mass from nothing","C":"All solutions become gases","D":"The solute's atomic number changes"}$q$::jsonb, $q$A$q$, $q$If solubility falls on cooling, the excess dissolved solute crystallizes.$q$),
  ($q$Solubility of Substances$q$, $q$Which statement distinguishes an unsaturated solution?$q$, $q${"A":"It has no solvent","B":"It can dissolve more solute at the same temperature","C":"It contains no molecules","D":"It has an insoluble solid at equilibrium"}$q$::jsonb, $q$B$q$, $q$Below saturation, further solute can still dissolve.$q$),
  ($q$Solubility of Substances$q$, $q$Solubility is 30 g per 100 g water. If 50 g solute is mixed with 100 g water at that temperature, how much remains undissolved at equilibrium?$q$, $q${"A":"50 g","B":"30 g","C":"20 g","D":"80 g"}$q$::jsonb, $q$C$q$, $q$At most 30 g dissolves; 50 − 30 = 20 g remains.$q$),
  ($q$Solubility of Substances$q$, $q$Why can heating a gas-containing solution make gas escape?$q$, $q${"A":"Gas atoms gain protons","B":"The liquid becomes magnetic","C":"Pressure must become infinite","D":"Gas solubility commonly decreases as temperature rises"}$q$::jsonb, $q$D$q$, $q$Warm liquid generally holds less dissolved gas, allowing bubbles to leave.$q$),
  -- Rates and equilibrium (16)
  ($q$Chemical Kinetics and Equilibrium$q$, $q$Why does powdered limestone react faster with acid than one equal-mass lump?$q$, $q${"A":"It exposes more surface area","B":"It has more calcium atoms","C":"It changes acid concentration","D":"It raises pressure automatically"}$q$::jsonb, $q$A$q$, $q$More exposed area permits more effective collisions per second.$q$),
  ($q$Chemical Kinetics and Equilibrium$q$, $q$Increasing temperature often speeds a reaction. Why?$q$, $q${"A":"Activation energy becomes negative","B":"More particles have energy above the activation barrier","C":"Particles stop colliding","D":"All products disappear"}$q$::jsonb, $q$B$q$, $q$Higher average kinetic energy increases the fraction of effective collisions.$q$),
  ($q$Chemical Kinetics and Equilibrium$q$, $q$What is the role of a catalyst in a reversible reaction?$q$, $q${"A":"It changes the equilibrium constant","B":"It changes the final equilibrium composition","C":"It speeds both forward and reverse reactions","D":"It prevents the reverse reaction"}$q$::jsonb, $q$C$q$, $q$A catalyst lowers activation barriers both ways; equilibrium is reached faster, not shifted.$q$),
  ($q$Chemical Kinetics and Equilibrium$q$, $q$At dynamic equilibrium, what is true of forward and reverse reaction rates?$q$, $q${"A":"Both must be zero","B":"Forward must be faster","C":"Reverse must be faster","D":"They are equal"}$q$::jsonb, $q$D$q$, $q$Both reactions continue at equal rates, keeping concentrations steady.$q$),
  ($q$Chemical Kinetics and Equilibrium$q$, $q$For N₂ + 3H₂ ⇌ 2NH₃, what does raising pressure favour at fixed temperature?$q$, $q${"A":"The side with fewer gas molecules: NH₃","B":"The side with more gas molecules: reactants","C":"Neither side because there are no gases","D":"Only decomposition of nitrogen"}$q$::jsonb, $q$A$q$, $q$Four gas molecules on the left become two on the right, so higher pressure favours ammonia.$q$),
  ($q$Chemical Kinetics and Equilibrium$q$, $q$If a reversible reaction is exothermic forward, how does cooling tend to shift its equilibrium?$q$, $q${"A":"Toward the endothermic direction","B":"Toward the exothermic direction","C":"Always toward the side with more moles","D":"It ends all reaction"}$q$::jsonb, $q$B$q$, $q$Cooling favours the direction that releases heat.$q$),
  ($q$Chemical Kinetics and Equilibrium$q$, $q$Why does high concentration usually increase reaction rate?$q$, $q${"A":"It removes every energy barrier","B":"It reduces particle count","C":"More particles per volume cause more collisions","D":"It makes reactants inert"}$q$::jsonb, $q$C$q$, $q$Collision frequency rises when reactant particles are more concentrated.$q$),
  ($q$Chemical Kinetics and Equilibrium$q$, $q$If a product is continuously removed from a reversible system, what shift is expected?$q$, $q${"A":"Toward reactants","B":"No shift ever","C":"Both directions stop","D":"Toward producing more product"}$q$::jsonb, $q$D$q$, $q$Le Châtelier's principle predicts a shift replacing removed product.$q$),
  ($q$Chemical Kinetics and Equilibrium$q$, $q$Why is collision alone insufficient for reaction?$q$, $q${"A":"Particles also need sufficient energy and suitable orientation","B":"Collisions occur only in solids","C":"Particles need zero kinetic energy","D":"A catalyst must always be present"}$q$::jsonb, $q$A$q$, $q$Effective collisions must overcome activation energy and align reactive sites.$q$),
  ($q$Chemical Kinetics and Equilibrium$q$, $q$A gas reaction has 1 mol of gaseous reactant and 2 mol of gaseous product. Which side is favoured by lowering pressure?$q$, $q${"A":"The one-mole side","B":"The two-mole side","C":"Neither because pressure affects only solids","D":"The reaction stops"}$q$::jsonb, $q$B$q$, $q$Lower pressure favours the side with more gas molecules.$q$),
  ($q$Chemical Kinetics and Equilibrium$q$, $q$What happens to an equilibrium constant when only a catalyst is added at unchanged temperature?$q$, $q${"A":"It doubles","B":"It halves","C":"It remains unchanged","D":"It becomes zero"}$q$::jsonb, $q$C$q$, $q$Equilibrium constant depends on temperature, not catalyst presence.$q$),
  ($q$Chemical Kinetics and Equilibrium$q$, $q$A reaction produces 60 mL gas in 30 s. What is its average gas production rate over that interval?$q$, $q${"A":"0.5 mL/s","B":"30 mL/s","C":"90 mL/s","D":"2 mL/s"}$q$::jsonb, $q$D$q$, $q$Average rate = volume/time = 60/30 = 2 mL/s.$q$),
  ($q$Chemical Kinetics and Equilibrium$q$, $q$Why may increasing gas pressure speed a gas-phase reaction?$q$, $q${"A":"Molecules are closer, increasing collision frequency","B":"The gas loses all energy","C":"Activation energy becomes infinite","D":"Molecules stop moving"}$q$::jsonb, $q$A$q$, $q$Compression raises gas concentration and the number of collisions per second.$q$),
  ($q$Chemical Kinetics and Equilibrium$q$, $q$What does a steady product concentration at equilibrium mean?$q$, $q${"A":"No molecules react","B":"Production and consumption occur at equal rates","C":"Reactants have vanished","D":"The vessel must be open"}$q$::jsonb, $q$B$q$, $q$Dynamic equilibrium keeps concentrations constant because opposite rates balance.$q$),
  ($q$Chemical Kinetics and Equilibrium$q$, $q$A reaction doubles its product amount from 10 g to 20 g in 5 min. What is average product formation rate over that interval?$q$, $q${"A":"6 g/min","B":"4 g/min","C":"2 g/min","D":"10 g/min"}$q$::jsonb, $q$C$q$, $q$Increase is 20 − 10 = 10 g over 5 min, giving 10/5 = 2 g/min.$q$),
  ($q$Chemical Kinetics and Equilibrium$q$, $q$How does adding more pure solid reactant to an equilibrium involving solids and gases usually affect equilibrium position if some solid was already present?$q$, $q${"A":"Always shifts right","B":"Always shifts left","C":"Eliminates the gas phase","D":"It does not shift solely because pure solid amount rises"}$q$::jsonb, $q$D$q$, $q$Pure solids have fixed activity in the equilibrium expression, provided a solid phase remains.$q$),
  -- Redox and electrochemistry (16)
  ($q$Redox Reactions$q$, $q$A magnesium atom becomes Mg²⁺. Has it been oxidized or reduced?$q$, $q${"A":"Oxidized by losing two electrons","B":"Reduced by gaining two electrons","C":"Neither because it is metal","D":"Reduced by losing protons"}$q$::jsonb, $q$A$q$, $q$Oxidation is electron loss: Mg → Mg²⁺ + 2e⁻.$q$),
  ($q$Redox Reactions$q$, $q$Cu²⁺ gains two electrons to form copper metal. What process occurs?$q$, $q${"A":"Oxidation","B":"Reduction","C":"Neutralization","D":"Hydrolysis"}$q$::jsonb, $q$B$q$, $q$Reduction is electron gain: Cu²⁺ + 2e⁻ → Cu.$q$),
  ($q$Redox Reactions$q$, $q$What is the oxidation state of sulfur in H₂SO₄? Take H as +1 and O as −2.$q$, $q${"A":"+2","B":"+4","C":"+6","D":"−2"}$q$::jsonb, $q$C$q$, $q$2(+1) + S + 4(−2) = 0; S = +6.$q$),
  ($q$Redox Reactions$q$, $q$What is the oxidation number of manganese in KMnO₄? K = +1 and O = −2.$q$, $q${"A":"+2","B":"+4","C":"+6","D":"+7"}$q$::jsonb, $q$D$q$, $q$1 + Mn + 4(−2) = 0; Mn = +7.$q$),
  ($q$Redox Reactions$q$, $q$An oxidizing agent causes another substance to lose electrons. What happens to the agent itself?$q$, $q${"A":"It gains electrons and is reduced","B":"It loses electrons and is oxidized","C":"It becomes a catalyst by definition","D":"It never changes oxidation state"}$q$::jsonb, $q$A$q$, $q$The oxidizing agent accepts electrons from the substance it oxidizes.$q$),
  ($q$Redox Reactions$q$, $q$In Zn + Cu²⁺ → Zn²⁺ + Cu, which species is the reducing agent?$q$, $q${"A":"Cu²⁺","B":"Zn","C":"Zn²⁺","D":"Cu"}$q$::jsonb, $q$B$q$, $q$Zinc donates electrons and is oxidized, so it reduces Cu²⁺.$q$),
  ($q$Redox Reactions$q$, $q$Where does oxidation occur in an electrochemical cell?$q$, $q${"A":"At the cathode always","B":"In the salt bridge only","C":"At the anode","D":"In the wire only"}$q$::jsonb, $q$C$q$, $q$Oxidation is defined as occurring at the anode in both galvanic and electrolytic cells.$q$),
  ($q$Redox Reactions$q$, $q$Where does reduction occur in an electrochemical cell?$q$, $q${"A":"At the anode","B":"Only in solution","C":"Only in the salt bridge","D":"At the cathode"}$q$::jsonb, $q$D$q$, $q$Electrons are gained at the cathode.$q$),
  ($q$Redox Reactions$q$, $q$What does a salt bridge do in a galvanic cell?$q$, $q${"A":"It allows ion flow to maintain charge balance","B":"It supplies all electrons to the wire","C":"It prevents any reaction","D":"It creates fuel from nothing"}$q$::jsonb, $q$A$q$, $q$Ions migrate through the bridge to prevent charge buildup in either half-cell.$q$),
  ($q$Redox Reactions$q$, $q$Why does a zinc-copper cell generate electrical energy spontaneously?$q$, $q${"A":"Both metals have identical tendencies to lose electrons","B":"A favourable redox reaction drives electrons through an external circuit","C":"Its salt bridge contains a battery","D":"Water alone supplies electricity"}$q$::jsonb, $q$B$q$, $q$Zinc oxidation and copper-ion reduction convert chemical free energy into electrical work.$q$),
  ($q$Redox Reactions$q$, $q$What is the oxidation number of oxygen in most ordinary oxides?$q$, $q${"A":"+2","B":"0","C":"−2","D":"−1 always"}$q$::jsonb, $q$C$q$, $q$Oxygen is normally −2 in oxides, with special exceptions such as peroxides.$q$),
  ($q$Redox Reactions$q$, $q$In Fe²⁺ → Fe³⁺ + e⁻, what happened to iron?$q$, $q${"A":"It gained an electron","B":"It gained a proton","C":"Its atomic number rose","D":"It was oxidized"}$q$::jsonb, $q$D$q$, $q$Iron loses one electron and its oxidation state rises from +2 to +3.$q$),
  ($q$Redox Reactions$q$, $q$In a simple galvanic cell, which path carries electrons between electrodes?$q$, $q${"A":"The external wire","B":"The salt bridge only","C":"The liquid solvent only","D":"The air above the cell only"}$q$::jsonb, $q$A$q$, $q$Electrons travel through the external conductor; ions move within the electrolyte and bridge.$q$),
  ($q$Redox Reactions$q$, $q$If an atom gains one electron without changing its nucleus, how does its charge change?$q$, $q${"A":"It becomes one unit more positive","B":"It becomes one unit more negative","C":"It must become neutral","D":"It doubles its mass number"}$q$::jsonb, $q$B$q$, $q$An electron carries one negative elementary charge.$q$),
  ($q$Redox Reactions$q$, $q$Why must oxidation and reduction occur together in a redox reaction?$q$, $q${"A":"No energy is transferred","B":"Both always occur in one atom","C":"Electrons lost by one species are gained by another","D":"Only oxygen can react"}$q$::jsonb, $q$C$q$, $q$Electron transfer conserves charge: a donor needs an acceptor.$q$),
  ($q$Redox Reactions$q$, $q$Which change is oxidation of carbon?$q$, $q${"A":"CO₂ carbon +4 to CO carbon +2","B":"Carbon 0 to methane carbon −4","C":"CO carbon +2 to carbon 0","D":"Carbon 0 to CO₂ carbon +4"}$q$::jsonb, $q$D$q$, $q$Carbon's oxidation number increases from 0 to +4 in CO₂.$q$),
  -- Carbon compounds (24)
  ($q$Chemistry of Carbon Compounds$q$, $q$Which formula represents an alkane?$q$, $q${"A":"C₃H₈","B":"C₃H₆","C":"C₃H₄","D":"C₃H₆O"}$q$::jsonb, $q$A$q$, $q$Open-chain alkanes follow CₙH₂ₙ₊₂; for n = 3, the formula is C₃H₈.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$Which functional group identifies an alcohol?$q$, $q${"A":"−COOH","B":"−OH","C":"−CHO","D":"−COO−"}$q$::jsonb, $q$B$q$, $q$Alcohols have a hydroxyl group attached to a carbon atom.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$What is the IUPAC name of CH₃CH₂CH₃?$q$, $q${"A":"Ethane","B":"Propene","C":"Propane","D":"Butane"}$q$::jsonb, $q$C$q$, $q$The molecule has three carbon atoms and only single carbon-carbon bonds: propane.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$Which compound contains a carbon-carbon double bond?$q$, $q${"A":"Ethane","B":"Methane","C":"Propane","D":"Ethene"}$q$::jsonb, $q$D$q$, $q$Ethene is the simplest alkene and contains C=C.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$Why do alkenes undergo addition reactions?$q$, $q${"A":"Their C=C bond can open to attach new atoms","B":"They contain no electrons","C":"They are all ionic","D":"They have no carbon"}$q$::jsonb, $q$A$q$, $q$The double bond includes a π bond that can break as new single bonds form.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$What product forms when ethene reacts completely with hydrogen over a catalyst?$q$, $q${"A":"Ethanol","B":"Ethane","C":"Ethanoic acid","D":"Ethyne"}$q$::jsonb, $q$B$q$, $q$Hydrogen adds across the double bond: C₂H₄ + H₂ → C₂H₆.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$What gas is released by complete combustion of a hydrocarbon besides water vapour?$q$, $q${"A":"Nitrogen dioxide","B":"Ammonia","C":"Carbon dioxide","D":"Hydrogen chloride"}$q$::jsonb, $q$C$q$, $q$With sufficient oxygen, carbon oxidizes fully to CO₂ and hydrogen forms water.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$Why is carbon monoxide dangerous when fuel burns with insufficient oxygen?$q$, $q${"A":"It is visible and harmless","B":"It makes water strongly acidic","C":"It has no chemical effect","D":"It binds strongly to haemoglobin, limiting oxygen transport"}$q$::jsonb, $q$D$q$, $q$CO competes with oxygen for haemoglobin binding sites.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$What distinguishes members of one homologous series?$q$, $q${"A":"Successive members differ by CH₂","B":"They have unrelated functional groups","C":"They have identical molar masses","D":"They are all elements"}$q$::jsonb, $q$A$q$, $q$A homologous series shares a functional group and adjacent members differ by one CH₂ unit.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$What happens when ethanol is oxidized fully with a suitable oxidant?$q$, $q${"A":"It becomes ethane","B":"It can form ethanoic acid","C":"It becomes sodium chloride","D":"It becomes carbon monoxide only"}$q$::jsonb, $q$B$q$, $q$A primary alcohol can be oxidized through an aldehyde to a carboxylic acid.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$What is the functional group of a carboxylic acid?$q$, $q${"A":"−OH only","B":"C=C","C":"−COOH","D":"−NH₂"}$q$::jsonb, $q$C$q$, $q$The carboxyl group contains both carbonyl and hydroxyl on the same carbon.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$Ethanol and ethanoic acid react to form an ester. What other small molecule is produced?$q$, $q${"A":"Oxygen","B":"Hydrogen","C":"Ammonia","D":"Water"}$q$::jsonb, $q$D$q$, $q$Esterification is a condensation reaction producing ester and water.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$Why does bromine solution lose its colour when mixed with ethene?$q$, $q${"A":"Bromine adds across the double bond","B":"Ethene has no bonds","C":"Water converts bromine into sodium","D":"Ethene is an ionic solid"}$q$::jsonb, $q$A$q$, $q$The C=C bond undergoes addition with Br₂, consuming coloured bromine.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$Which substance is a structural isomer of butane?$q$, $q${"A":"Propane","B":"2-Methylpropane","C":"Pentane","D":"Butene"}$q$::jsonb, $q$B$q$, $q$Both butane and 2-methylpropane have formula C₄H₁₀ but different carbon skeletons.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$What does fractional distillation of crude oil primarily exploit?$q$, $q${"A":"Different magnetic properties","B":"Different colours only","C":"Different boiling ranges","D":"Different atomic numbers only"}$q$::jsonb, $q$C$q$, $q$Hydrocarbon fractions vaporize and condense at different temperatures.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$Why is cracking useful in petroleum refining?$q$, $q${"A":"It turns hydrocarbons into metals","B":"It removes all carbon","C":"It only freezes fuel","D":"It converts larger hydrocarbons into smaller useful molecules"}$q$::jsonb, $q$D$q$, $q$Cracking breaks long chains, producing shorter alkanes and alkenes.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$Which molecular formula fits a four-carbon alkene with one double bond and no ring?$q$, $q${"A":"C₄H₈","B":"C₄H₁₀","C":"C₄H₆","D":"C₄H₄"}$q$::jsonb, $q$A$q$, $q$Acyclic monoalkenes follow CₙH₂ₙ, so n = 4 gives C₄H₈.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$Why are saturated hydrocarbons called saturated?$q$, $q${"A":"They contain dissolved salt","B":"Their carbons carry the maximum possible hydrogens for that skeleton","C":"They contain only double bonds","D":"They all dissolve in water"}$q$::jsonb, $q$B$q$, $q$Single-bonded carbon skeletons have no C=C or C≡C bond to add hydrogen across.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$How many carbon atoms are in pentane?$q$, $q${"A":"Three","B":"Four","C":"Five","D":"Six"}$q$::jsonb, $q$C$q$, $q$The prefix pent- denotes five carbon atoms.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$A molecule has the group −COO− linking two carbon groups. To which family does it belong?$q$, $q${"A":"Alkane","B":"Alcohol","C":"Alkene","D":"Ester"}$q$::jsonb, $q$D$q$, $q$The −COO− linkage between carbon groups is characteristic of an ester.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$What is formed by addition polymerization of ethene?$q$, $q${"A":"Poly(ethene)","B":"Ethanol","C":"Ethanoic acid","D":"Glucose"}$q$::jsonb, $q$A$q$, $q$Ethene double bonds open and many units join into poly(ethene).$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$Why are many hydrocarbons poorly soluble in water?$q$, $q${"A":"They contain free ions","B":"They are largely nonpolar while water is polar","C":"They have no electrons","D":"They are all solids"}$q$::jsonb, $q$B$q$, $q$Nonpolar hydrocarbons interact weakly with polar water molecules.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$What does the general formula CₙH₂ₙ₊₂ describe for acyclic hydrocarbons?$q$, $q${"A":"Alkenes","B":"Alkynes","C":"Alkanes","D":"Alcohols"}$q$::jsonb, $q$C$q$, $q$Saturated open-chain hydrocarbons have 2n + 2 hydrogen atoms.$q$),
  ($q$Chemistry of Carbon Compounds$q$, $q$When a long-chain alkane cracks, why may one product decolourize bromine solution?$q$, $q${"A":"It is always water","B":"It must be a metal","C":"It has no carbon","D":"It may be an alkene with a double bond"}$q$::jsonb, $q$D$q$, $q$Cracking often makes alkenes, which add bromine across C=C.$q$),
  -- Industry and environment (8)
  ($q$Chemistry, Industry and Environment$q$, $q$What main product is sought in the Haber process?$q$, $q${"A":"Ammonia","B":"Sulfuric acid","C":"Ethanol","D":"Sodium chloride"}$q$::jsonb, $q$A$q$, $q$The Haber process combines nitrogen and hydrogen to produce ammonia.$q$),
  ($q$Chemistry, Industry and Environment$q$, $q$Why does an industrial process recycle unreacted feedstock?$q$, $q${"A":"To increase waste","B":"To improve overall material use","C":"To stop production","D":"To make equilibrium impossible"}$q$::jsonb, $q$B$q$, $q$Recycling reactants can increase effective yield and reduce resource waste.$q$),
  ($q$Chemistry, Industry and Environment$q$, $q$Which gas contributes directly to acid rain after oxidation in air?$q$, $q${"A":"Argon","B":"Helium","C":"Sulfur dioxide","D":"Neon"}$q$::jsonb, $q$C$q$, $q$SO₂ can oxidize and dissolve in rainwater to form acidic solutions.$q$),
  ($q$Chemistry, Industry and Environment$q$, $q$Why should untreated industrial wastewater not enter a river?$q$, $q${"A":"Rivers have no organisms","B":"It always improves oxygen supply","C":"It turns all fish into plants","D":"Toxic substances can harm aquatic life and people"}$q$::jsonb, $q$D$q$, $q$Chemical contaminants may damage ecosystems and drinking-water quality.$q$),
  ($q$Chemistry, Industry and Environment$q$, $q$Why does burning fossil fuel add to atmospheric warming?$q$, $q${"A":"It releases CO₂, a greenhouse gas","B":"It removes every atmospheric gas","C":"It creates no combustion products","D":"It converts sunlight into solid rock"}$q$::jsonb, $q$A$q$, $q$Complete combustion releases carbon dioxide, which absorbs outgoing infrared radiation.$q$),
  ($q$Chemistry, Industry and Environment$q$, $q$What is a benefit of using a catalyst in a large-scale reaction?$q$, $q${"A":"It becomes the main product","B":"It can lower energy needs by speeding reaction at milder conditions","C":"It removes the need for reactants","D":"It guarantees zero waste"}$q$::jsonb, $q$B$q$, $q$Catalysts can make a useful rate possible without excessively harsh operating conditions.$q$),
  ($q$Chemistry, Industry and Environment$q$, $q$Why is local air-quality monitoring useful near a chemical plant?$q$, $q${"A":"It replaces emission controls","B":"It proves pollution never occurs","C":"It detects harmful emissions and checks controls","D":"It increases smoke output"}$q$::jsonb, $q$C$q$, $q$Measurements help identify exposure and assess whether mitigation works.$q$),
  ($q$Chemistry, Industry and Environment$q$, $q$A factory replaces a hazardous solvent with a safer one. Which principle is being applied?$q$, $q${"A":"Increase toxicity","B":"Ignore waste","C":"Use more fuel","D":"Reduce hazard at its source"}$q$::jsonb, $q$D$q$, $q$Choosing a safer input prevents harm before waste treatment is needed.$q$),
  -- Basic biochemistry and synthetic polymers (8)
  ($q$Basic Biochemistry and Polymers$q$, $q$What links amino acids together in a protein?$q$, $q${"A":"Peptide bonds","B":"Ionic sodium bonds","C":"Metallic bonds only","D":"Hydrogen gas"}$q$::jsonb, $q$A$q$, $q$A carboxyl group and amino group join by condensation to form a peptide bond.$q$),
  ($q$Basic Biochemistry and Polymers$q$, $q$Why can heating strongly change a protein's function?$q$, $q${"A":"It always adds amino acids","B":"Its three-dimensional shape may denature","C":"It turns every protein into metal","D":"It removes all atoms"}$q$::jsonb, $q$B$q$, $q$Heat can disrupt interactions maintaining the shape required for activity.$q$),
  ($q$Basic Biochemistry and Polymers$q$, $q$Which two functional groups occur in an ordinary amino acid?$q$, $q${"A":"Alkene and ester","B":"Ketone and ether","C":"Amino and carboxyl","D":"Two hydroxyl groups only"}$q$::jsonb, $q$C$q$, $q$Amino acids contain −NH₂ and −COOH groups, with ionized forms in solution.$q$),
  ($q$Basic Biochemistry and Polymers$q$, $q$What is a monomer in polymer chemistry?$q$, $q${"A":"A finished giant molecule","B":"A solvent only","C":"A metal catalyst","D":"A small molecule that can join into a chain"}$q$::jsonb, $q$D$q$, $q$Many monomer units link to form a polymer.$q$),
  ($q$Basic Biochemistry and Polymers$q$, $q$Why can poly(ethene) persist in the environment?$q$, $q${"A":"Its carbon-chain structure biodegrades slowly","B":"It dissolves instantly in rain","C":"It contains living cells","D":"It evaporates at room temperature"}$q$::jsonb, $q$A$q$, $q$Microorganisms generally break its stable carbon backbone down only slowly.$q$),
  ($q$Basic Biochemistry and Polymers$q$, $q$Which nutrient supplies amino acids needed for tissue growth and repair?$q$, $q${"A":"Pure water","B":"Protein","C":"Sodium chloride","D":"Sand"}$q$::jsonb, $q$B$q$, $q$Digestion breaks dietary proteins into amino acids for building body proteins.$q$),
  ($q$Basic Biochemistry and Polymers$q$, $q$How does an addition polymer differ from a condensation polymer?$q$, $q${"A":"It always has no carbon","B":"It must be a natural protein","C":"Addition joins monomers without releasing a small molecule","D":"It cannot have repeating units"}$q$::jsonb, $q$C$q$, $q$Addition polymerization joins unsaturated monomers without a small by-product, unlike many condensation reactions.$q$),
  ($q$Basic Biochemistry and Polymers$q$, $q$Why are biodegradable alternatives sometimes preferred to persistent plastics?$q$, $q${"A":"They must be stronger in every use","B":"They never need resources","C":"They make all recycling unnecessary","D":"They may reduce long-term accumulation under suitable conditions"}$q$::jsonb, $q$D$q$, $q$If appropriately processed, biodegradable materials can break down faster, though impacts depend on conditions.$q$)
)
insert into public.questions (subject_id, exam_type, source, year, topic, prompt, options, correct_answer, explanation)
select subject.id, subject.exam_type, $q$original$q$, null,
       candidate.topic, candidate.prompt, candidate.options, candidate.correct_answer, candidate.explanation
from candidates as candidate
cross join public.subjects as subject
where subject.id = '35f721a4-9160-4078-8b60-52462f2f18ac'::uuid
  and lower(subject.exam_type::text) = 'waec'
  and not exists (select 1 from public.questions as existing where existing.subject_id = subject.id and existing.prompt = candidate.prompt);
commit;
